On aura donc
(107)
$\begin{aligned}
V_{J,L}&=\bigcup_{\substack{j\in J\\\ell\in L}}\underbrace{V_j\cap V_\ell}_{V_{j,\ell}}
\deleted{=\bigcup_{\substack{j\in J\\\ell\in L\\j\le L}}}\\
&=\bigcup_{i\in J\cap L}V_i\cup\bigcup_{\substack{j<\ell\\j\in J,\ell\in L}}V_{j\ell}\cup\bigcup_{\substack{\ell<j\\j\in J,\ell\in L}}V_{\ell j}
\end{aligned}$

\margin{\uline{NB} ici les drapeau\unsure{x}
en prenant les
$i_0<\mathord{-}\unsure{i_\beta|i_1}<i_n$, \unsure{les} $i_\alpha\in J\cup L$
$i_0\in J,\ i_n\in L$, donc les
$i_\alpha$ qui sont $\in J$ forment un \unsure{segm|segm.}
initial, les $i_\beta\in L$ un segm. final\textsuperscript{*}}

\margin{* la réunion des deux drapeaux
est $\{i_0,\mathord{\cdot}\mathord{-}i_n\}$; l'intersection
\deleted{\illegible{1}} \unsure{est} $\phi$ si $J\cap L=\phi$ ...}
